const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),path=require('node:path');
function engine(){const c={structuredClone};c.importScripts=()=>vm.runInContext(fs.readFileSync(path.join(__dirname,'../property-planner.js'),'utf8'),c);vm.createContext(c);vm.runInContext(fs.readFileSync(path.join(__dirname,'../simulation-worker.js'),'utf8').replace("require('./browser-entry.cjs');","globalThis.sim=require('./sim.cjs');"),c);return c.sim;}
test('nine terrain levels are seeded, finite, distinct, with a truly flat first level',()=>{const sim=engine(),signatures=new Set();for(let level=1;level<=9;level++){const a=sim.environment(43,540,level).w.terrain,b=sim.environment(43,540,level).w.terrain;assert.equal(JSON.stringify(a),JSON.stringify(b));const h=a.grid.heights.flat();assert(h.every(Number.isFinite));if(level===1)assert.equal(new Set(h).size,1);signatures.add(JSON.stringify(h));}assert.equal(signatures.size,9);assert.notEqual(JSON.stringify(sim.environment(43,540,9).w.terrain.grid),JSON.stringify(sim.environment(44,540,9).w.terrain.grid));});
test('farm siting uses the requested terrain at flat and extreme settings',()=>{const sim=engine();for(const topology of [1,9]){const p=sim.grow({seed:43,size:540,horses:6,mode:'grazing',topology},8);assert(p.valid,topology+': '+p.failures);assert.equal(p.world.terrain.topology.level,topology);const e=sim.environment(43,540,topology);assert(p.buildings.every(b=>e.slope(b.cx,b.cz)<.15));}});
